//! Words as Lucene's `StandardTokenizer` finds them, for the analyzers that follow
//! Lucene's (`english-lucene`, the light stemmers, `dutch-lucene`, `cjk-lucene` and the
//! dictionary analyzers).
//!
//! Lucene 9.11.1's tokenizer is generated by JFlex from a grammar of UAX #29's word
//! boundary rules over Unicode 12.1, with rules of its own for emoji and for the scripts
//! of South East Asia. This module follows that grammar rule for rule, with the
//! character properties of Unicode 12.1 ([`super::standard_tables`]):
//!
//! * Letters and digits join into one word, and so do two letters around an apostrophe,
//!   a period or a colon (`aren't`, `l'homme`, `u.s.a`) and two digits around a comma, a
//!   period or a semicolon (`3,14`). An underscore joins what is around it. A Hebrew
//!   letter keeps a following apostrophe, and two Hebrew letters join around a double
//!   quote.
//! * A run of Katakana, a run of Hangul and a run of Thai, Lao, Khmer or Myanmar letters
//!   is one word. Each Han ideograph and each Hiragana character is a word of its own.
//! * An emoji is a word, with its presentation selector, skin tone modifier, the emoji
//!   it joins with zero width joiners and its tag sequence, and so are a keycap
//!   sequence and a pair of regional indicators (a flag).
//! * Combining marks, format characters and joiners stay with the character before them.
//!   Everything else separates words and is dropped.
//!
//! Each word is the longest match of the grammar's rules at its start, and of two
//! matches of the same length the earlier rule's wins, as in JFlex. Lucene's scanner
//! reads at most 255 UTF-16 code units of a word, so a longer word is cut where the
//! longest match within those units ends, and the rest is scanned as new text.

use super::standard_tables::RANGES;
use tantivy::tokenizer::{Token, TokenStream, Tokenizer};

/// The longest word, in UTF-16 code units, as Lucene's default `maxTokenLength`.
const MAX_UNITS: usize = 255;

/// The tokenizer of the analyzers that follow Lucene's.
#[derive(Clone, Default)]
pub(crate) struct StandardTokenizer;

pub(crate) struct StandardTokenStream {
    tokens: std::vec::IntoIter<Token>,
    token: Token,
}

impl Tokenizer for StandardTokenizer {
    type TokenStream<'a> = StandardTokenStream;

    fn token_stream<'a>(&'a mut self, text: &'a str) -> StandardTokenStream {
        StandardTokenStream {
            tokens: tokens(text).into_iter(),
            token: Token::default(),
        }
    }
}

impl TokenStream for StandardTokenStream {
    fn advance(&mut self) -> bool {
        match self.tokens.next() {
            Some(t) => {
                self.token = t;
                true
            }
            None => false,
        }
    }

    fn token(&self) -> &Token {
        &self.token
    }

    fn token_mut(&mut self) -> &mut Token {
        &mut self.token
    }
}

// The Word_Break values in bits 0 to 3 of a property word (standard-tables.py's order).
const ALETTER: u16 = 1;
const HEBREW_LETTER: u16 = 2;
const NUMERIC: u16 = 3;
const KATAKANA: u16 = 4;
const MID_LETTER: u16 = 5;
const MID_NUM_LET: u16 = 6;
const SINGLE_QUOTE: u16 = 7;
const MID_NUM: u16 = 8;
const EXTEND_NUM_LET: u16 = 9;
const DOUBLE_QUOTE: u16 = 10;
const REGIONAL_INDICATOR: u16 = 11;
const FORMAT: u16 = 12;
const EXTEND: u16 = 13;
const ZWJ: u16 = 14;
// The scripts in bits 4 and 5.
const HAN: u16 = 1 << 4;
const HIRAGANA: u16 = 2 << 4;
const HANGUL: u16 = 3 << 4;
const SCRIPT: u16 = 3 << 4;
// Line_Break=Complex_Context and the emoji properties.
const COMPLEX_CONTEXT: u16 = 1 << 6;
const EMOJI: u16 = 1 << 7;
const EMOJI_MODIFIER: u16 = 1 << 8;
const EMOJI_MODIFIER_BASE: u16 = 1 << 9;
const EXTENDED_PICTOGRAPHIC: u16 = 1 << 10;

/// The properties of the code points below this, looked up directly.
const DIRECT: usize = 0x800;

static DIRECT_PROPS: [u16; DIRECT] = direct_props();

const fn direct_props() -> [u16; DIRECT] {
    let mut t = [0u16; DIRECT];
    let mut r = 0;
    while r < RANGES.len() {
        let (first, last, p) = RANGES[r];
        let mut c = first as usize;
        while c <= last as usize && c < DIRECT {
            t[c] = p;
            c += 1;
        }
        r += 1;
    }
    t
}

fn props(c: char) -> u16 {
    let u = c as u32;
    if (u as usize) < DIRECT {
        return DIRECT_PROPS[u as usize];
    }
    match RANGES.binary_search_by(|&(first, last, _)| {
        if last < u {
            std::cmp::Ordering::Less
        } else if first > u {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(i) => RANGES[i].2,
        Err(_) => 0,
    }
}

/// Whether a character is of the Han script.
pub(super) fn is_han(u: u32) -> bool {
    char::from_u32(u).is_some_and(|c| props(c) & SCRIPT == HAN)
}

/// The kind of a word, as Lucene's tokenizer types its tokens: the CJK bigram filter of
/// `cjk-lucene` pairs the characters of the CJK kinds.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) enum Kind {
    /// letters and digits of any other script or a mix, numbers, emoji and the runs of
    /// South East Asian scripts
    Alphanum,
    Ideographic,
    Hiragana,
    /// a run of Katakana only
    Katakana,
    /// a run of Hangul only
    Hangul,
}

/// A character of the text: its byte offset, the character and its properties.
#[derive(Clone, Copy)]
struct Ch {
    at: usize,
    c: char,
    p: u16,
}

impl Ch {
    fn wb(self) -> u16 {
        self.p & 0xF
    }
    /// Format, Extend or ZWJ: what stays with the character before it
    fn efz(self) -> bool {
        matches!(self.wb(), FORMAT | EXTEND | ZWJ)
    }
    /// as `efz`, without the presentation selectors, for the emoji rules
    fn efz_sans_selector(self) -> bool {
        self.efz() && !matches!(self.c, '\u{FE0E}' | '\u{FE0F}')
    }
    fn ah_letter(self) -> bool {
        matches!(self.wb(), ALETTER | HEBREW_LETTER)
    }
    fn mid_letter(self) -> bool {
        matches!(self.wb(), MID_LETTER | MID_NUM_LET | SINGLE_QUOTE)
    }
    fn mid_num(self) -> bool {
        matches!(self.wb(), MID_NUM | MID_NUM_LET | SINGLE_QUOTE)
    }
    fn hangul(self) -> bool {
        self.p & SCRIPT == HANGUL && self.ah_letter()
    }
    fn keycap_base(self) -> bool {
        matches!(self.c, '0'..='9' | '#' | '*')
    }
    /// Emoji that are not regional indicators, keycap bases, accidental emoji (`©`,
    /// `®`, `™`, `〰`, `〽`) or modifiers, or Extended_Pictographic
    fn emoji_char(self) -> bool {
        self.p & EXTENDED_PICTOGRAPHIC != 0
            || (self.p & EMOJI != 0
                && self.wb() != REGIONAL_INDICATOR
                && !self.keycap_base()
                && !matches!(self.c, '©' | '®' | '™' | '\u{3030}' | '\u{303D}')
                && self.p & EMOJI_MODIFIER == 0)
    }
}

/// The scanner's view of the text from one word's start: the characters, and the end of
/// the window that Lucene's buffer holds.
struct Scan<'a> {
    cs: &'a [Ch],
    lim: usize,
}

impl Scan<'_> {
    fn at(&self, i: usize) -> Option<Ch> {
        (i < self.lim).then(|| self.cs[i])
    }

    fn is(&self, i: usize, f: impl Fn(Ch) -> bool) -> bool {
        self.at(i).is_some_and(f)
    }

    /// After the Format, Extend and ZWJ characters from `i`.
    fn ext(&self, mut i: usize) -> usize {
        while self.is(i, Ch::efz) {
            i += 1;
        }
        i
    }

    /// The end of a character that satisfies `f` at `i` with the characters that stay
    /// with it.
    fn unit(&self, i: usize, f: impl Fn(Ch) -> bool) -> Option<usize> {
        self.is(i, f).then(|| self.ext(i + 1))
    }

    /// A run of such units from `i`: its end, or `i`.
    fn run(&self, mut i: usize, f: impl Fn(Ch) -> bool + Copy) -> usize {
        while let Some(j) = self.unit(i, f) {
            i = j;
        }
        i
    }

    /// Every end of `ExtFmtZwjSansPresSel` from `i`: `i` and each position up to the
    /// first other character.
    fn sans_ends(&self, i: usize) -> std::ops::RangeInclusive<usize> {
        let mut j = i;
        while self.is(j, Ch::efz_sans_selector) {
            j += 1;
        }
        i..=j
    }

    /// The ends of an emoji, an emoji with a presentation selector or an emoji
    /// modifier sequence at `i` (`EmojiCharOrPresSeqOrModSeq`).
    fn emoji_seq(&self, i: usize, out: &mut Vec<usize>) {
        let mut z = i;
        loop {
            if self.is(z, Ch::emoji_char) {
                for e in self.sans_ends(z + 1) {
                    out.push(e);
                    if self.is(e, |c| c.c == '\u{FE0F}') {
                        out.push(e + 1);
                    }
                }
            }
            if self.is(z, |c| c.p & EMOJI_MODIFIER_BASE != 0) {
                for e in self.sans_ends(z + 1) {
                    if self.is(e, |c| c.p & EMOJI_MODIFIER != 0) {
                        out.extend(self.sans_ends(e + 1));
                    }
                }
            }
            if !self.is(z, |c| c.wb() == ZWJ) {
                break;
            }
            z += 1;
        }
        if self.is(i, |c| c.p & EMOJI_MODIFIER != 0) {
            out.extend(self.sans_ends(i + 1));
        }
    }

    /// The emoji rule: a sequence joined by zero width joiners or followed by a tag
    /// sequence, a keycap sequence, or a pair of regional indicators.
    fn emoji(&self, i: usize) -> usize {
        let mut best = i;
        let first = self.cs[i];
        if first.emoji_char()
            || first.wb() == ZWJ
            || first.p & (EMOJI_MODIFIER | EMOJI_MODIFIER_BASE) != 0
        {
            let mut ends = Vec::new();
            self.emoji_seq(i, &mut ends);
            ends.sort_unstable();
            ends.dedup();
            let firsts = ends.clone();
            let mut frontier = ends.clone();
            while !frontier.is_empty() {
                let mut next = Vec::new();
                for &e in &frontier {
                    if self.is(e, |c| c.wb() == ZWJ) {
                        self.emoji_seq(e + 1, &mut next);
                    }
                }
                next.sort_unstable();
                next.dedup();
                next.retain(|e| ends.binary_search(e).is_err());
                ends.extend_from_slice(&next);
                ends.sort_unstable();
                frontier = next;
            }
            for &e in &firsts {
                let mut j = e;
                while self.is(j, |c| ('\u{E0020}'..='\u{E007E}').contains(&c.c)) {
                    j += 1;
                }
                if j > e && self.is(j, |c| c.c == '\u{E007F}') {
                    best = best.max(j + 1);
                }
            }
            best = best.max(ends.last().copied().unwrap_or(i));
        }
        if first.keycap_base() {
            for e in self.sans_ends(i + 1) {
                for p in [Some(e), self.is(e, |c| c.c == '\u{FE0F}').then_some(e + 1)]
                    .into_iter()
                    .flatten()
                {
                    if self.is(p, |c| c.c == '\u{20E3}') {
                        best = best.max(*self.sans_ends(p + 1).end());
                    }
                }
            }
        }
        if first.wb() == REGIONAL_INDICATOR {
            let j = self.ext(i + 1);
            if let Some(k) = self.unit(j, |c| c.wb() == REGIONAL_INDICATOR) {
                best = best.max(k);
            }
        }
        best
    }

    /// The number rule: digits joined by underscores, or around a comma, a period or a
    /// semicolon, with underscores before and after.
    fn numeric(&self, i: usize) -> usize {
        let enl = |c: Ch| c.wb() == EXTEND_NUM_LET;
        let num = |c: Ch| c.wb() == NUMERIC;
        let j = self.run(i, enl);
        let Some(mut j) = self.unit(j, num) else {
            return i;
        };
        loop {
            let k = self.run(j, enl);
            if let Some(n) = self.unit(k, num) {
                j = n;
                continue;
            }
            if k == j
                && let Some(m) = self.unit(j, Ch::mid_num)
                && let Some(n) = self.unit(m, num)
            {
                j = n;
                continue;
            }
            return k;
        }
    }

    /// The word rule, as a set of states of its automaton over the units from `i`.
    fn word(&self, i: usize) -> usize {
        // before the first letter or digit, only underscores so far
        const PRE: u16 = 1;
        // after underscores that follow a letter, a digit or Katakana
        const E: u16 = 2;
        const K: u16 = 4;
        // after a letter
        const A: u16 = 8;
        // after a letter and a joining punctuation mark, waiting for a letter
        const AM: u16 = 16;
        // after a Hebrew letter, which a quote may follow
        const H: u16 = 32;
        // after a Hebrew letter and a double quote, waiting for a Hebrew letter
        const HD: u16 = 64;
        // after a Hebrew letter with its quote
        const HQ: u16 = 128;
        const N: u16 = 256;
        // after a digit and a joining punctuation mark, waiting for a digit
        const NM: u16 = 512;
        const ACCEPT: u16 = E | K | A | HQ | N;
        let mut states = PRE;
        let mut best = i;
        let mut j = i;
        while let Some(c) = self.at(j) {
            let any_core = states & (PRE | E) != 0;
            let next_part = any_core || states & (A | HQ | N) != 0;
            let mut s = 0;
            let wb = c.wb();
            if c.ah_letter() {
                if next_part {
                    s |= A;
                    if wb == HEBREW_LETTER {
                        s |= H;
                    }
                }
                if states & AM != 0 {
                    s |= A;
                }
                if wb == HEBREW_LETTER && states & HD != 0 {
                    s |= HQ;
                }
            }
            if wb == NUMERIC && (next_part || states & NM != 0) {
                s |= N;
            }
            if wb == KATAKANA && (any_core || states & K != 0) {
                s |= K;
            }
            if wb == EXTEND_NUM_LET {
                if states & PRE != 0 {
                    s |= PRE;
                }
                if states & (E | K | A | HQ | N) != 0 {
                    s |= E;
                }
            }
            if c.mid_letter() && states & A != 0 {
                s |= AM;
            }
            if c.mid_num() && states & N != 0 {
                s |= NM;
            }
            if wb == SINGLE_QUOTE && states & H != 0 {
                s |= HQ;
            }
            if wb == DOUBLE_QUOTE && states & H != 0 {
                s |= HD;
            }
            if s == 0 {
                break;
            }
            states = s;
            j = self.ext(j + 1);
            if states & ACCEPT != 0 {
                best = j;
            }
        }
        best
    }
}

/// The words of `text` with their byte offsets and positions.
pub(crate) fn tokens(text: &str) -> Vec<Token> {
    typed_tokens(text).into_iter().map(|(t, _)| t).collect()
}

/// The words of `text` with their byte offsets, positions and kinds.
pub(crate) fn typed_tokens(text: &str) -> Vec<(Token, Kind)> {
    let cs: Vec<Ch> = text
        .char_indices()
        .map(|(at, c)| Ch { at, c, p: props(c) })
        .collect();
    let byte = |i: usize| cs.get(i).map_or(text.len(), |c| c.at);
    // units[i]: the UTF-16 code units before character i
    let mut units = Vec::with_capacity(cs.len() + 1);
    let mut n = 0;
    units.push(0);
    for c in &cs {
        n += c.c.len_utf16();
        units.push(n);
    }
    let mut out: Vec<(Token, Kind)> = Vec::new();
    let mut lim = 0;
    let mut i = 0;
    while i < cs.len() {
        while lim < cs.len() && units[lim + 1] - units[i] <= MAX_UNITS {
            lim += 1;
        }
        let scan = Scan { cs: &cs, lim };
        let c = cs[i];
        // the rules in the grammar's order: the longest match wins, and the earlier
        // rule of two of the same length
        let mut best = (i, Kind::Alphanum);
        let mut consider = |end: usize, kind: Kind| {
            if end > best.0 {
                best = (end, kind);
            }
        };
        if c.p & (EMOJI | EXTENDED_PICTOGRAPHIC | EMOJI_MODIFIER | EMOJI_MODIFIER_BASE) != 0
            || matches!(c.wb(), ZWJ | REGIONAL_INDICATOR)
        {
            consider(scan.emoji(i), Kind::Alphanum);
        }
        let wb = c.wb();
        if matches!(wb, NUMERIC | EXTEND_NUM_LET) {
            consider(scan.numeric(i), Kind::Alphanum);
        }
        if c.hangul() {
            consider(scan.run(i, Ch::hangul), Kind::Hangul);
        }
        if wb == KATAKANA {
            consider(scan.run(i, |c| c.wb() == KATAKANA), Kind::Katakana);
        }
        if c.ah_letter() || matches!(wb, NUMERIC | KATAKANA | EXTEND_NUM_LET) {
            consider(scan.word(i), Kind::Alphanum);
        }
        if c.p & COMPLEX_CONTEXT != 0 {
            consider(scan.run(i, |c| c.p & COMPLEX_CONTEXT != 0), Kind::Alphanum);
        }
        match c.p & SCRIPT {
            HAN => consider(scan.ext(i + 1), Kind::Ideographic),
            HIRAGANA => consider(scan.ext(i + 1), Kind::Hiragana),
            _ => {}
        }
        let (end, kind) = best;
        if end == i {
            i += 1;
            continue;
        }
        let (from, to) = (byte(i), byte(end));
        out.push((
            Token {
                offset_from: from,
                offset_to: to,
                position: out.len(),
                text: text[from..to].to_string(),
                position_length: 1,
            },
            kind,
        ));
        i = end;
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn texts(s: &str) -> Vec<String> {
        tokens(s).into_iter().map(|t| t.text).collect()
    }

    /// The tokens of a line as StandardTokens.java prints them, with Lucene's types,
    /// except that numbers, emoji and South East Asian runs are all `<ALPHANUM>`.
    pub(crate) fn typed_line(line: &str) -> String {
        let u16_at = |b: usize| line[..b].encode_utf16().count();
        typed_tokens(line)
            .into_iter()
            .map(|(t, k)| {
                let kind = match k {
                    Kind::Alphanum => "<ALPHANUM>",
                    Kind::Ideographic => "<IDEOGRAPHIC>",
                    Kind::Hiragana => "<HIRAGANA>",
                    Kind::Katakana => "<KATAKANA>",
                    Kind::Hangul => "<HANGUL>",
                };
                format!(
                    "{}@{}-{}:{kind}",
                    t.text,
                    u16_at(t.offset_from),
                    u16_at(t.offset_to)
                )
            })
            .collect::<Vec<_>>()
            .join(" ")
    }

    #[test]
    fn words_join_across_inner_punctuation() {
        assert_eq!(
            texts("John's cars aren't U.S.A. e.g. 3,14 l’arbre"),
            [
                "John's",
                "cars",
                "aren't",
                "U.S.A",
                "e.g",
                "3,14",
                "l’arbre"
            ]
        );
        // punctuation at the edges separates
        assert_eq!(
            texts("'quoted' end. 1,2,3, x:y"),
            ["quoted", "end", "1,2,3", "x:y"]
        );
        // letters and digits join, and underscores join both
        assert_eq!(texts("abc123 foo_bar __ _x"), ["abc123", "foo_bar", "_x"]);
        // a period between a letter and a digit separates them
        assert_eq!(texts("a.1 1.a"), ["a", "1", "1", "a"]);
        assert_eq!(texts("Straße naïve café"), ["Straße", "naïve", "café"]);
        // a combining mark stays with its letter, and so does a joiner
        assert_eq!(texts("cafe\u{301} x"), ["cafe\u{301}", "x"]);
        assert_eq!(texts("ab\u{200D}cd"), ["ab\u{200D}cd"]);
        // a virama joins the letters of a Bengali word
        assert_eq!(texts("বিদ্যা"), ["বিদ্যা"]);
        // a Hebrew letter keeps its quote
        assert_eq!(texts("א\"ב צ'"), ["א\"ב", "צ'"]);
    }

    #[test]
    fn cjk_and_south_east_asian_characters() {
        // each ideograph and Hiragana character alone, Katakana and Hangul as runs
        assert_eq!(
            texts("東京にコーヒー한국어"),
            ["東", "京", "に", "コーヒー", "한국어"]
        );
        let kinds: Vec<Kind> = typed_tokens("東にコ한a").into_iter().map(|t| t.1).collect();
        assert_eq!(
            kinds,
            [
                Kind::Ideographic,
                Kind::Hiragana,
                Kind::Katakana,
                Kind::Alphanum
            ]
        );
        // a run of Thai is one word
        assert_eq!(texts("ภาษาไทย ok"), ["ภาษาไทย", "ok"]);
    }

    #[test]
    fn emoji() {
        assert_eq!(texts("hello 😀 world"), ["hello", "😀", "world"]);
        // a skin tone, a family joined by zero width joiners, a flag, a keycap and a
        // presentation selector stay with their emoji
        assert_eq!(
            texts("👍🏽 👨\u{200D}👩\u{200D}👧 🇫🇷🇩🇪 1\u{FE0F}\u{20E3} ❤\u{FE0F}"),
            [
                "👍🏽",
                "👨\u{200D}👩\u{200D}👧",
                "🇫🇷",
                "🇩🇪",
                "1\u{FE0F}\u{20E3}",
                "❤\u{FE0F}"
            ]
        );
        assert_eq!(texts("© ♥ #"), ["©", "♥"]);
    }

    #[test]
    fn offsets_positions_and_long_words() {
        let t = tokens("ab, cd");
        assert_eq!(
            t.iter()
                .map(|t| (t.position, t.offset_from, t.offset_to))
                .collect::<Vec<_>>(),
            [(0, 0, 2), (1, 4, 6)]
        );
        let long = "x".repeat(600);
        assert_eq!(
            texts(&long).iter().map(|w| w.len()).collect::<Vec<_>>(),
            [255, 255, 90]
        );
        // the limit counts UTF-16 code units and never splits a character
        let wide = "𐐀".repeat(260);
        assert_eq!(
            texts(&wide)
                .iter()
                .map(|w| w.chars().count())
                .collect::<Vec<_>>(),
            [127, 127, 6]
        );
    }

    /// Lucene's tokens, offsets and types of the lines of standard-tokenizer.in, which
    /// scripts/text-lucene-compare/tokens.sh writes, with every character class of
    /// Unicode 12.1 that the grammar distinguishes in several contexts.
    #[test]
    fn tokens_agree_with_lucene() {
        let dir =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/lucene-analyzers");
        let input = std::fs::read_to_string(dir.join("standard-tokenizer.in")).unwrap();
        let expected = std::fs::read_to_string(dir.join("standard-tokenizer.out")).unwrap();
        let mut failures = Vec::new();
        let mut checked = 0;
        for (line, e) in input.split('\n').zip(expected.split('\n')) {
            let e = ["<NUM>", "<EMOJI>", "<SOUTHEAST_ASIAN>"]
                .iter()
                .fold(e.to_string(), |e, t| e.replace(t, "<ALPHANUM>"));
            let got = typed_line(line);
            checked += 1;
            if got != e {
                failures.push(format!("{line:?}: lucene {e:?}, sparkles {got:?}"));
            }
        }
        assert!(checked > 19_000, "{checked} lines");
        assert!(
            failures.is_empty(),
            "{} of {checked} lines differ:\n{}",
            failures.len(),
            failures[..failures.len().min(20)].join("\n")
        );
    }

    /// The tokens of each line of `$SPARKLES_STANDARD_IN` as
    /// scripts/text-lucene-compare/StandardTokens.java prints Lucene's, written to
    /// `$SPARKLES_STANDARD_OUT` (for comparing the tokenizers over many lines).
    #[test]
    #[ignore]
    fn tokenize_file() {
        let input =
            std::fs::read_to_string(std::env::var("SPARKLES_STANDARD_IN").unwrap()).unwrap();
        let mut out = String::new();
        for line in input.split('\n') {
            out.push_str(&typed_line(line));
            out.push('\n');
        }
        std::fs::write(std::env::var("SPARKLES_STANDARD_OUT").unwrap(), out).unwrap();
    }
}
